import{_ as n,o as h,c as a,a3 as r}from"./chunks/framework.MGD2uYU7.js";const m=JSON.parse('{"title":"Wireframes — định hình giao diện 30 màn (SC-01 → SC-49)","description":"","frontmatter":{},"headers":[],"relativePath":"wireframes/index.md","filePath":"wireframes/index.md","lastUpdated":null}'),e={name:"wireframes/index.md"};function d(i,t,c,o,s,u){return h(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="wireframes-—-đinh-hinh-giao-dien-30-man-sc-01-→-sc-49" tabindex="-1">Wireframes — định hình giao diện 30 màn (SC-01 → SC-49) <a class="header-anchor" href="#wireframes-—-đinh-hinh-giao-dien-30-man-sc-01-→-sc-49" aria-label="Permalink to &quot;Wireframes — định hình giao diện 30 màn (SC-01 → SC-49)&quot;">​</a></h1><p><strong>Dành cho</strong>: Designer (dựng Figma từ đây), Dev FE (hiểu behavior trước khi code), PM/QA (đối chiếu docs/05). <strong>Nguồn chân lý hành vi</strong>: <a href="/anphuc-docs/guide/05-ui-ux-spec.html">docs/05 UI/UX Spec</a> + <a href="/anphuc-docs/guide/03-use-cases.html">docs/03 Use Cases</a> + <a href="/anphuc-docs/guide/08-business-rules-permissions.html">docs/08 Business Rules</a>. Wireframe <strong>không</strong> thay thế các doc đó — nó chỉ &quot;vẽ ra&quot; những gì doc đã chốt.</p><div class="tip custom-block"><p class="custom-block-title">Wireframe là gì, không là gì</p><p>Đây là bản vẽ <strong>lo-fi (thấp fidelity)</strong>: grayscale, ảnh là khung chéo, chữ là thanh xám. Mục đích là chốt <strong>bố cục — thông tin nào ở đâu — hành vi gì xảy ra — trạng thái nào phải có</strong>. KHÔNG chốt màu sắc, font chữ, khoảng cách, phong cách. Designer <strong>toàn quyền quyết định visual</strong> trong Figma, miễn là giữ đủ thông tin, trạng thái và copy đã chú thích.</p></div><h2 id="quy-uoc-đoc-ban-ve" tabindex="-1">Quy ước đọc bản vẽ <a class="header-anchor" href="#quy-uoc-đoc-ban-ve" aria-label="Permalink to &quot;Quy ước đọc bản vẽ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ký hiệu</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td>Khung chéo + chữ &quot;ẢNH&quot;</td><td>Vị trí ảnh (gallery, avatar, thumbnail) — designer quyết định style</td></tr><tr><td>Thanh xám dài/ngắn</td><td>Văn bản (tiêu đề/nội dung) — độ dài tương đối, không phải chữ thật</td></tr><tr><td><span style="color:#0b57d0;"><strong>①②③</strong></span></td><td>Callout đánh số — giải thích hành vi ở <strong>bảng Chú thích</strong> dưới mỗi bản vẽ, kèm ID rule (BR-/FR-/SC-) để trace</td></tr><tr><td>Nền xanh dương</td><td>Nút/hành động chính (primary CTA) — vị trí chốt, màu chính thức do designer chọn theo tokens docs/05 §7</td></tr><tr><td>Khung đỏ + số đếm ngược</td><td>Đồng hồ/countdown nghiệp vụ (phiên đấu giá, hạn 24h thanh toán)</td></tr><tr><td>Nhãn đen &quot;TRẠNG THÁI: ...&quot;</td><td>Bản vẽ cho một trạng thái cụ thể của màn (Loading/Empty/Error/Data — quy tắc 4 trạng thái docs/05 §1.4)</td></tr><tr><td>Số tiền <code>1.250.000.000 ₫</code></td><td><strong>Số thật theo nghiệp vụ</strong> — copy chuẩn, không sửa, không lorem ipsum</td></tr></tbody></table><p><strong>Mọi màn dữ liệu phải thiết kế đủ 4 trạng thái</strong>: Loading (skeleton) → Empty (CTA hướng dẫn) → Error (thông điệp + Thử lại + traceId) → Data. Wireframe mỗi màn vẽ ít nhất trạng thái Data + các trạng thái đặc thù quan trọng; designer bổ sung đủ 4 trong Figma (checklist handoff docs/05 §8).</p><h2 id="danh-muc-30-man" tabindex="-1">Danh mục 30 màn <a class="header-anchor" href="#danh-muc-30-man" aria-label="Permalink to &quot;Danh mục 30 màn&quot;">​</a></h2><h3 id="public-—-khach-chua-đang-nhap-xem-đuoc-8-man" tabindex="-1">Public — khách chưa đăng nhập xem được (8 màn) <a class="header-anchor" href="#public-—-khach-chua-đang-nhap-xem-đuoc-8-man" aria-label="Permalink to &quot;Public — khách chưa đăng nhập xem được (8 màn)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Màn</th><th>Độ phức tạp</th><th>Điểm cần chú ý nhất</th></tr></thead><tbody><tr><td><a href="/anphuc-docs/wireframes/public/sc-01-trang-chu.html">SC-01 Trang chủ</a></td><td>Trung bình</td><td>Hero + search; 6 tin mới; 3 phiên sắp mở có countdown; CTA &quot;Đăng bán&quot;</td></tr><tr><td><a href="/anphuc-docs/wireframes/public/sc-02-danh-sach-tin.html">SC-02 Danh sách tin</a></td><td>Trung bình</td><td>Filter rail + card grid; VIP badge; URL sync (share được)</td></tr><tr><td><a href="/anphuc-docs/wireframes/public/sc-03-chi-tiet-tin.html">SC-03 Chi tiết tin</a></td><td>Cao</td><td>Gallery lightbox; CTA đổi theo trạng thái tin &amp; KYC người xem; chủ nhà ẩn danh &quot;đã xác minh ✓&quot;</td></tr><tr><td><a href="/anphuc-docs/wireframes/public/sc-04-chi-tiet-du-an.html">SC-04 Chi tiết dự án</a></td><td>Thấp</td><td>Giá trần/m² phải nổi bật (lý do tin không vượt giá này)</td></tr><tr><td><a href="/anphuc-docs/wireframes/public/sc-05-danh-sach-phien.html">SC-05 Danh sách phiên</a></td><td>Trung bình</td><td>3 tab Sắp mở / LIVE / Kết thúc; card countdown; LIVE pulse đỏ</td></tr><tr><td><a href="/anphuc-docs/wireframes/public/sc-06-phien-dau-gia-live.html">⭐ SC-06 Phiên đấu giá LIVE</a></td><td><strong>Rất cao — màn quan trọng nhất</strong></td><td>Feed bid ẩn danh + countdown + bid form + anti-snipe + overlay kết quả; xem §4 docs/05</td></tr><tr><td><a href="/anphuc-docs/wireframes/public/sc-07-bang-goi.html">SC-07 Bảng gói VIP</a></td><td>Thấp</td><td>3 pricing cards + so sánh + FAQ; không &quot;sale lòe&quot;</td></tr><tr><td><a href="/anphuc-docs/wireframes/public/sc-08-hoi-dap.html">SC-08 Hướng dẫn / Hỏi đáp</a></td><td>Thấp</td><td>Static: điều kiện mua NOXH, quy chế đấu giá, cọc — chỗ đặt copy pháp lý</td></tr></tbody></table><h3 id="auth-2-man" tabindex="-1">Auth (2 màn) <a class="header-anchor" href="#auth-2-man" aria-label="Permalink to &quot;Auth (2 màn)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Màn</th><th>Điểm cần chú ý nhất</th></tr></thead><tbody><tr><td><a href="/anphuc-docs/wireframes/auth/sc-09-dang-nhap.html">SC-09 Đăng nhập</a></td><td>&quot;Quên mật khẩu?&quot; → <strong>popover gọi CS</strong> (v1 KHÔNG có form self-reset); 429 rate-limit countdown 15 phút</td></tr><tr><td><a href="/anphuc-docs/wireframes/auth/sc-10-dang-ky.html">SC-10 Đăng ký</a></td><td>Password strength meter; lỗi 409 email trùng; đăng ký xong → deep-link return về trang đang xem</td></tr></tbody></table><h3 id="user-—-sau-đang-nhap-10-man" tabindex="-1">User — sau đăng nhập (10 màn) <a class="header-anchor" href="#user-—-sau-đang-nhap-10-man" aria-label="Permalink to &quot;User — sau đăng nhập (10 màn)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Màn</th><th>Độ phức tạp</th><th>Điểm cần chú ý nhất</th></tr></thead><tbody><tr><td><a href="/anphuc-docs/wireframes/user/sc-20-dashboard.html">SC-20 Dashboard</a></td><td>Trung bình</td><td>Checklist onboarding KYC→tin→VIP; widgets tổng hợp</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-21-xac-minh-kyc.html">SC-21 Xác minh KYC</a></td><td>Cao</td><td>3 bước; upload CCCD 2 mặt; cảnh báo dữ liệu nhạy cảm (NĐ13); banner REJECTED + reason nguyên văn</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-22-wizard-dang-tin.html">SC-22 Wizard đăng tin</a></td><td><strong>Rất cao</strong></td><td>5 bước + autosave draft; check giá trần realtime; check trùng số sổ realtime; hết quota → modal VIP</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-23-tin-cua-toi.html">SC-23 Tin của tôi</a></td><td>Trung bình</td><td>Table tabs theo trạng thái; sửa chỉ khi DRAFT/REJECTED; rút tin = confirm vĩnh viễn</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-24-dang-ky-phien-coc.html">SC-24 Đăng ký phiên + cọc</a></td><td><strong>Rất cao</strong></td><td>Quy chế modal (bắt buộc cuộn hết + tick); breakdown cọc; 2 kênh VNPay / chuyển khoản thủ công (bill + nút copy)</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-25-don-thanh-toan.html">SC-25 Đơn thanh toán</a></td><td>Cao</td><td>Breakdown <code>giá trúng + phí − cọc</code>; đồng hồ 24h; EXPIRED = mất cọc (giải thích rõ, không đổ lỗi)</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-26-goi-cua-toi.html">SC-26 Gói của tôi</a></td><td>Thấp</td><td>Usage X/hạn mức; đổi gói = mất phần còn lại → confirm dialog</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-27-lich-xem-nha.html">SC-27 Lịch xem nhà</a></td><td>Trung bình</td><td>2 tab (mình đặt / mình nhận — vai chủ nhà); picker chặn &lt;24h, ngoài 08:00–20:00; tối đa 3 lịch chờ</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-28-thong-bao.html">SC-28 Thông báo</a></td><td>Thấp</td><td>List + unread; click → deep-link đúng entity</td></tr><tr><td><a href="/anphuc-docs/wireframes/user/sc-29-ho-so.html">SC-29 Hồ sơ</a></td><td>Thấp</td><td>Email READ-ONLY; đổi mật khẩu</td></tr></tbody></table><h3 id="admin-—-ops-an-phuc-layout-rieng-uu-tien-desktop-10-man" tabindex="-1">Admin — Ops An Phuc, layout riêng, ưu tiên desktop (10 màn) <a class="header-anchor" href="#admin-—-ops-an-phuc-layout-rieng-uu-tien-desktop-10-man" aria-label="Permalink to &quot;Admin — Ops An Phuc, layout riêng, ưu tiên desktop (10 màn)&quot;">​</a></h3><p>Pattern chung mọi màn admin: DataTable server-side (filter/sort/page) + drawer chi tiết + action confirm <strong>reason bắt buộc</strong> + SLA badge quá hạn (đỏ nhấp nháy) + toast sau mutation + export CSV.</p><table tabindex="0"><thead><tr><th>Màn</th><th>Điểm cần chú ý nhất</th></tr></thead><tbody><tr><td><a href="/anphuc-docs/wireframes/admin/sc-40-admin-dashboard.html">SC-40 Admin Dashboard</a></td><td>Số liệu: users, tin, phiên, GMV (North Star), SLA</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-41-queue-duyet-kyc.html">SC-41 Queue duyệt KYC</a></td><td>SLA 48h; drawer xem ảnh CCCD signed; approve/reject reason 10–500 ký tự</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-42-queue-duyet-tin.html">SC-42 Queue duyệt tin</a></td><td>SLA 24h; checklist đối chiếu sổ/giá-vs-trần/ảnh</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-43-quan-ly-du-an.html">SC-43 Quản lý dự án</a></td><td>CRUD + trường giá trần/m² (load-bearing BR-HS-06)</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-44-danh-sach-phien.html">SC-44 Danh sách phiên</a></td><td>Tabs theo trạng thái phiên; cancel chỉ DRAFT/PUBLISHED</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-45-form-tao-phien.html">SC-45 Form tạo phiên</a></td><td>Validate: mở ≥+7 ngày, đóng đăng ký = mở−24h, bước giá 1–20%, cọc 1–20% min 10tr</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-46-monitor-phien-live.html">SC-46 Monitor phiên LIVE</a></td><td>Feed + participants + extend log; nút kết thúc sớm (reason)</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-47-xac-nhan-chuyen-khoan.html">SC-47 Xác nhận chuyển khoản</a></td><td>Đối chiếu bill content <code>ANPHUC &lt;paymentId&gt;</code> + amount khớp từng đồng; SLA 2h</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-48-quan-ly-nguoi-dung.html">SC-48 Quản lý người dùng</a></td><td>Search + drawer + suspend/activate/reset password; chặn suspend người đang trong phiên</td></tr><tr><td><a href="/anphuc-docs/wireframes/admin/sc-49-audit-log.html">SC-49 Audit log</a></td><td><strong>View-only tuyệt đối</strong> — không nút xóa/sửa ở bất kỳ đâu</td></tr></tbody></table><h2 id="cach-gop-y-wireframe" tabindex="-1">Cách góp ý wireframe <a class="header-anchor" href="#cach-gop-y-wireframe" aria-label="Permalink to &quot;Cách góp ý wireframe&quot;">​</a></h2><p>Comment <strong>ngay dưới trang wireframe tương ứng</strong> (khung Giscus cuối trang) — ghi rõ: màn nào, khu vực nào (số callout ①②③ nếu có), đề xuất gì. Ví dụ:</p><blockquote><p>&quot;SC-06 ④: trên mobile nên đổi thứ tự tab thành Bid trước Feed, vì người dùng vào để bid chứ không để đọc feed.&quot;</p></blockquote><p>Góp ý <strong>thay đổi nghiệp vụ/con số</strong> (vd: &quot;đổi hạn 24h thành 48h&quot;) → PM phải đối chiếu docs/08 trước; wireframe chỉ đổi sau khi doc gốc đổi.</p><h2 id="trang-thai-hoan-thanh" tabindex="-1">Trạng thái hoàn thành <a class="header-anchor" href="#trang-thai-hoan-thanh" aria-label="Permalink to &quot;Trạng thái hoàn thành&quot;">​</a></h2><p><strong>Cả 30 màn đã vẽ đầy đủ (2026-10-10)</strong>, đồng bộ docs/05 v1.1. Mỗi trang gồm: layout desktop + mobile 360, các modal/trạng thái đặc thù, trạng thái lỗi &amp; biên theo quy tắc 4 trạng thái, chú thích hành vi ①②③ trace về BR/FR/UC, và checklist cho designer dựng Figma. Bản vẽ chỉ đổi khi doc gốc đổi — góp ý nghiệp vụ (con số, thời hạn, quyền) cần PM đối chiếu docs/08 trước khi sửa wireframe.</p>',22)])])}const l=n(e,[["render",d]]);export{m as __pageData,l as default};
